import json,csv,re
from pathlib import Path
D=Path(__file__).resolve().parent
items=[];talks=[];problems=[];corrections=[]
def talk(record,date,speaker,pages,title,summary):
 talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(record,pages,kind,title,notes,statement,reconstruction,cls,fate,status,refs=(),literal='correct with missing hypotheses',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high',speaker=None):
 n=1+sum(x['record']==record for x in items)
 x=dict(id=f'1985-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of November 2026: '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
 if speaker:x['speaker']=speaker
 items.append(x);return x['id']
def save():
 for name,data in [('talks',talks),('items',items),('problems',problems)]:
  (D/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def correction(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
 corrections.append([page,place,reads,should,evidence,applies,typ])

# The manuscript, rather than the overlapping catalogue ranges, determines these boundaries.
talk(641,'1985-09-09','M. M. Kapranov','P001199-P001200','Baker functions, spinors, and twistor transforms',r'''The talk joins the construction of line bundles from exponential principal parts to twistor descriptions of Yang--Mills equations. The manuscript distinguishes the newly generalized Baker-function construction from material inspired by Witten, Clifford algebra, and the four-dimensional Penrose--Ward correspondence. A. Goncharov supplies the spinor explanation. The ten-dimensional projective diagram is too compressed to support an additional theorem. Earlier related exposition occurs at 1975-374.4, 1975-379.7, 1977-432.15, 1978-455.6, and 1982-592.7; these are connections, not evidence for a recurring open problem.''')
item(641,'P001199','definition','Baker functions with an exponential singularity',r'''The heading is \ru{Функция Бейкера произв. мн-зия}; the notes write \(\varphi=e^{q(z)}\varphi _0\), with \(\varphi _0\) holomorphic, and require meromorphic behavior elsewhere. The English ``arbitrary set'' mistranslates the abbreviated Russian for manifold.''',r'''Let \(X\) be a complex manifold, \(D\) an effective Cartier divisor, and \(q\in H^0(X,\mathcal O_X(D)/\mathcal O_X)\). Choose local meromorphic lifts \(q_i\). A scalar Baker function of exponential type \(q\) is meromorphic on \(X\setminus |D|\), with \(e^{-q_i}\varphi\) meromorphically extendible across \(D\) on each chart. The notebook's holomorphic condition is a more restrictive local version. Allowed poles and normalization must be specified before asserting existence or uniqueness.''',r'''The global gluing data and the distinction between holomorphic and meromorphic prefactors are supplied. No existence theorem for arbitrary prescribed data is attributed to the talk.''','A',r'''\citet[\S3.3]{kapranovmanin1986twistor} give this construction; the paper was received on 10 October 1985 and printed in 1986. Its abstract and full text were checked.''',r'''Established construction; existence and dimensions require the specified line bundle and divisor data. This is not an unsolved existence claim.''',['kapranovmanin1986twistor'])
item(641,'P001199','construction','Exponential principal parts and the Picard group',r'''The displayed chain is \(H^0(\mathcal O(D)/\mathcal O)\xrightarrow{\delta}H^1(\mathcal O)\to H^1(\mathcal O^*)\).''',r'''For the preceding \(X,D\), the connecting map of \(0\to\mathcal O_X\to\mathcal O_X(D)\to\mathcal O_X(D)/\mathcal O_X\to0\), followed by the sheaf exponential, associates to \(q\) a line bundle with transition functions \(\exp(q_i-q_j)\). Changing the lifts changes this cocycle by a coboundary. This construction produces the image of these principal parts, not necessarily every element of \(\operatorname{Pic}X\).''',r'''The cocycle and the limitation on surjectivity make explicit what the arrows mean.''','E',r'''\citet[\S3.1--2]{kapranovmanin1986twistor} explicitly describe the cohomological linearization as known, while employing it in their 1985--86 construction.''',r'''Standard sheaf-cohomological construction; the generalized Baker-function application is the adjacent A item.''',['kapranovmanin1986twistor'])
item(641,'P001199','construction','Super light rays of dimension one even and eight odd',r'''``Now something inspired by Witten'': in \(\mathbb C^{10/16}\), consider lines of dimension \(1/8\). The even space has a nondegenerate symmetric form, and its chosen line is isotropic.''',r'''Write the complex supertranslation space as \(V^{10|16}\), whose odd space is a half-spin module \(S^+\) for \(\operatorname{Spin}(10,\mathbb C)\). A nonzero null vector \(v\) determines an eight-dimensional subspace \(\ker(c(v):S^+\to S^-)\). The corresponding supertranslation subsupergroup has dimension \(1|8\); its translates are the super light rays. Their bracket is the spin-equivariant symmetric map \(\operatorname{Sym}^2 S^+\to V\).''',r'''The slash is interpreted as superdimension, not division. Clifford multiplication and the supertranslation bracket complete the omitted definition; ordinary affine linear subspaces alone do not encode this bracket.''','E',r'''Witten's preprint circulated in May 1985, as recorded in \citet[reference 52; \S4.2]{kapranovmanin1986twistor}; \citet{witten1986twistor} appeared in March 1986. Witten metadata and the explicit construction in Kapranov--Manin were read.''',r'''An established supertwistor construction already circulating before this talk; the 1986 print date does not make it a new September announcement.''',['kapranovmanin1986twistor','witten1986twistor'],match='partial')
item(641,'P001199','claim','Spin(10), the isotropic-line stabilizer, and two eight-dimensional spinors',r'''A. Goncharov explains that the sixteen-dimensional space is the spinor representation of \(SO(10)\), and that the stabilizer of an isotropic line leads to \(SO(8)\) and two invariant eight-dimensional subspaces.''',r'''The linear half-spin representation belongs to \(\operatorname{Spin}(10,\mathbb C)\). For an isotropic line \(\ell\subset V\), the quotient \(\ell^\perp/\ell\) is nondegenerate of dimension eight. Restriction to the semisimple factor \(\operatorname{Spin}(8,\mathbb C)\) of a chosen Levi subgroup of the stabilizer gives \(S^+|_{\operatorname{Spin}(8)}\simeq S_8^+\oplus S_8^-\), with both summands eight-dimensional. A Levi splitting must not be confused with a splitting preserved by the entire parabolic.''',r'''The covering group and the Levi qualification repair the shorthand; no canonical pair of complementary subbundles under the full parabolic is asserted.''','E',r'''The classical Clifford-module framework is in \citet[\S\S3--5]{atiyahbottshapiro1964clifford}; the eight-dimensional null kernel used here is explicit in \citet[\S4.2]{kapranovmanin1986twistor}.''',r'''Standard representation theory. The literal \(SO(10)\) assertion requires the spin double cover, or a projective representation.''',['atiyahbottshapiro1964clifford','kapranovmanin1986twistor'],literal='false as written',match='partial',speaker='A. Goncharov')
item(641,'P001200','theorem','The complex Clifford algebra in ten dimensions',r'''The generators satisfy \(e_i e_k+e_k e_i=2\delta_{ik}I\); the notes give algebra dimension \(2^{10}\) and matrices of size \(2^5\). A marginal vector formula omits the factor two.''',r'''For a ten-dimensional complex vector space with nondegenerate symmetric form \(b\), use the convention \(uv+vu=2b(u,v)1\). Then \(\operatorname{Cl}(V,b)\cong M_{32}(\mathbb C)\), with vector-space dimension \(1024\). Its irreducible module has dimension \(32\), and the even subalgebra preserves its two half-spin summands of dimension \(16\).''',r'''The even/odd distinction explains why the preceding superspace uses sixteen spinors whereas the full Clifford module has dimension thirty-two.''','E',r'''This is the classical complex Clifford classification; see \citet[\S4, Table 1]{atiyahbottshapiro1964clifford}, published in 1964.''',r'''Established; only the normalization inconsistency in the margin needs correction.''',['atiyahbottshapiro1964clifford'],literal='correct with missing hypotheses')
item(641,'P001200','claim','Inner automorphisms yield a projective orthogonal action',r'''An orthogonal transformation acts on the Clifford algebra; its automorphism is inner, and the notes conclude that this produces a representation of the orthogonal group.''',r'''The orthogonal action on \(M_{32}(\mathbb C)\) gives a homomorphism \(O(10,\mathbb C)\to\operatorname{PGL}_{32}(\mathbb C)\). Implementing matrices are determined only up to scalars, so innerness alone supplies a projective representation. Passing to \(\operatorname{Pin}(10)\), or to \(\operatorname{Spin}(10)\) above \(SO(10)\), supplies the usual linear spin representation.''',r'''The scalar ambiguity is essential and is absent from the notebook's inference.''','E',r'''\citet[\S3]{atiyahbottshapiro1964clifford} construct the spin double cover and its Clifford-module action. This predates the talk by two decades.''',r'''The projective statement is correct; the unqualified ordinary representation of \(SO(10)\) is false.''',['atiyahbottshapiro1964clifford'],literal='false as written',match='partial',development='annotated')
item(641,'P001200','claim','Flatness along super light rays and ten-dimensional Yang--Mills constraints',r'''The curvature is said to vanish on the indicated superlines, equivalently giving a generalized self-dual Yang--Mills equation.''',r'''For a holomorphic connection on ten-dimensional supertranslation space, flatness on every \(1|8\) super light ray means that the pullback curvature vanishes on the tangent distribution of each ray. Witten's correspondence relates the appropriate supersymmetric Yang--Mills constraints to bundles on the space of such rays that are trivial on the incidence fibers. This is a supersymmetric integrability statement, not the ordinary four-dimensional equation \(F=\pm *F\) transplanted to ten dimensions.''',r'''The notes do not list the superconnection constraints or bundle triviality hypotheses. Accordingly the correspondence is identified, but a complete component-field theorem is not reconstructed as something stated in this talk.''','E',r'''The pre-September circulation of Witten's construction is documented above; see \citet[Introduction (f), \S4]{kapranovmanin1986twistor} and \citet{witten1986twistor}.''',r'''The identifiable correspondence is established. The notebook is insufficient to specify exactly which component equations the speaker imposed.''',['kapranovmanin1986twistor','witten1986twistor'],match='partial',confidence='medium')
item(641,'P001200','remark','The twelve-dimensional projective diagram',r'''A diagram places \(\mathbb C^{12}\setminus\{0\}\), a projective space with an overwritten superscript, and \(Q^{10}\) together; the last phrase mentions a covering supermanifold.''',r'''One elementary repair is forced: \((\mathbb C^{12}\setminus\{0\})/\mathbb C^*=\mathbb P^{11}\). A nonsingular quadric hypersurface therein has dimension ten. The manuscript does not determine the arrows, covering, superdimension, or intended relation between this quadric and the eight-dimensional quadric of null directions in \(\mathbb C^{10}\).''',r'''The dimension check is ours. Identifying the diagram with a particular compactification or supertwistor space would require data not present on the page.''','F',r'''The explicit ten-dimensional correspondence in \citet[\S4.2]{kapranovmanin1986twistor} was compared, but it does not establish the identity of every arrow in this separate diagram.''',r'''Unresolved identification of a diagram, not an open theorem. The projective superscript is retained as an ambiguity in the corrections ledger.''',['kapranovmanin1986twistor'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low')
item(641,'P001200','construction','Lines in projective three-space and null two-planes',r'''The Radon--Penrose discussion identifies lines in \(\mathbb P^3\) with \(\operatorname{Gr}(2,4)\), and draws the two families of null two-planes in a tangent space.''',r'''For \(W\in\operatorname{Gr}(2,\mathbb C^4)\), \(T_W\operatorname{Gr}(2,4)\simeq\operatorname{Hom}(W,\mathbb C^4/W)\). The determinant is a quadratic form valued in a one-dimensional line, hence defines a conformal class. Its rank-one cone has two rulings by two-dimensional totally null linear spaces: maps with a fixed one-dimensional kernel, or maps with image in a fixed line. These give the two types of maximal null surfaces.''',r'''The tangent-space description makes the diagram precise and explains why only a conformal class, rather than a preferred metric, is intrinsic.''','E',r'''This is the classical twistor incidence geometry used in \citet[Introduction (a)]{kapranovmanin1986twistor}; the four-dimensional instanton correspondence was published by \citet{atiyahward1977instantons} in 1977.''',r'''Standard geometry; no claim of a new classification is present.''',['kapranovmanin1986twistor','atiyahward1977instantons'],match='partial')
item(641,'P001200','remark','Rank two and two relative-position parameters',r'''The Grassmannian is said to have rank two: pairs of its points require two numbers, whereas pairs of points on a sphere require one.''',r'''Equip \(\mathbb C^4\) with a positive Hermitian form and consider the compact homogeneous space \(U(4)/(U(2)\times U(2))\). A pair of two-planes is classified under simultaneous unitary transformations by its two principal angles \(0\leq\theta_1\leq\theta_2\leq\pi/2\), obtained as singular values \(\cos\theta_i\) of orthogonal projection from one plane to the other. This is the rank-two statement. Under arbitrary complex linear transformations, this continuous two-parameter assertion would be false.''',r'''The compact metric and acting group are supplied; they are needed to make the comparison with a sphere correct. The classification follows directly from singular-value decomposition.''','E',r'''The notebook gives an elementary homogeneous-space observation, not a problem. The modern statement above is a direct linear-algebraic verification, rather than a publication match inferred from the twistor bibliography.''',r'''Correct in the compact Hermitian interpretation; the source does not specify that interpretation.''',[],match='none found',verification='indirect',confidence='medium')
item(641,'P001200','theorem','Curvature on alpha-surfaces and the Penrose--Ward transform',r'''Vanishing curvature on one family of null surfaces is equated with self-duality. The connection then gives a bundle, without a connection, on the parameter space of those surfaces.''',r'''On a suitable complex four-dimensional conformally flat domain, the vanishing of the curvature restricted to every alpha-plane is equivalent to the vanishing of one of its two Hodge components. Which component is called self-dual depends on the chosen orientation. If the relevant alpha-surfaces and incidence fibers satisfy the usual local simple-connectivity/triviality conditions, horizontal sections along them define a holomorphic bundle on twistor space, trivial on each twistor line. Conversely such a bundle reconstructs the connection up to gauge.''',r'''Locality, triviality on twistor lines, and the orientation convention are necessary additions. Flatness on each alpha-surface does not imply vanishing of all curvature.''','E',r'''The correspondence predates the talk: \citet{atiyahward1977instantons}, with its complex formulation reviewed in \citet[Introduction (a)]{kapranovmanin1986twistor}. The latter exposition was read; the former publisher record was checked.''',r'''Established correspondence. The statement here is local complex geometry; real instantons require additional reality and global conditions.''',['atiyahward1977instantons','kapranovmanin1986twistor'],match='partial')
save()

talk(642,'1985-09-09','V. I. Arnold','P001201','Zeros of Abelian integrals and Petrov nonoscillation',r'''Arnold asks for bounds on zeros of Abelian integrals and reports Petrov's sharp cubic-Hamiltonian theorem. The page then moves through Chebyshev spaces, Picard--Fuchs equations, vanishing periods, and two Jacobian-algebra examples. The compactness and degree qualifications are essential. A general linear-independence sentence is false literally; it is not used to justify Petrov's theorem.''')
item(642,'P001201','problem','Uniform bounds for zeros of polynomial Abelian integrals',r'''For \(I(c)=\oint_{H=c}(P\,dx+Q\,dy)\), the opening question asks how many zeros it can have.''',r'''Given degree bounds \(\deg H\leq d\) and \(\max(\deg P,\deg Q)\leq m\), seek a finite bound depending only on \((d,m)\) for the total isolated zeros, with multiplicity, of the real period branches over all regular compact ovals of \(H\). Identically zero branches contribute no isolated zeros. Integration over an entire noncompact real level set is not intended.''',r'''Degree bounds and regular oval branches are supplied to make the notebook's question definite. No sharp asymptotic conjecture, or claim concerning higher return-map variations, is imputed to Arnold.''','B',r'''\citet[Theorem 2 and \S1.2]{binyamininovikovyakovenko2010zeros} give a uniform double-exponential degree bound. The preprint appeared in August 2008; publication followed in 2010.''',r'''The finite-uniform-bound question is solved in this precise sense. The cited theorem does not settle Hilbert's full sixteenth problem, cycles born from singular levels, or perturbations whose first Abelian integral vanishes identically.''',['binyamininovikovyakovenko2010zeros'],problem='GP-1985-01')
item(642,'P001201','theorem','Petrov: the cubic Hamiltonian gives an n-dimensional Chebyshev space',r'''For \(H=y^2/2+P_3(x)\), \(\deg P,\deg Q\leq n\), Arnold states that the period space has dimension \(n\) and that a nonzero period has fewer than \(n\) zeros. The manuscript's personal-name wording is retained in the correction ledger; the theorem identifies the author as G. S. Petrov.''',r'''Let \(n\geq1\), and let \(H=y^2+x^3-x\). On its maximal interval of regular compact ovals, the real vector space \(\{\oint_{\gamma(t)}(P\,dx+Q\,dy):\deg P,\deg Q\leq n\}\) has dimension \(n\); every nonzero element has at most \(n-1\) zeros counted with multiplicity. The bound is attained. A real cubic potential with two distinct real critical points reduces to this model by affine changes and rescaling; without such a real oval annulus the stated real zero-count assertion has no domain.''',r'''The normalized model, multiplicities, and nondegenerate real oval interval are supplied. The statement concerns the dimension of the image of the period map, not the much larger space of polynomial one-forms.''','B',r'''This is \citet[Theorem 1 and \S2.1, Russian pp.~46--47]{petrov1986elliptic}. The paper was received on 24 January 1985 and printed in 1986; the September talk therefore reports work already completed, by someone other than its speaker.''',r'''A proved sharp result. Its restriction to cubic potentials must not be promoted to a Chebyshev assertion for all Hamiltonians.''',['petrov1986elliptic'],literal='correct with missing hypotheses')
item(642,'P001201','method','Picard--Fuchs systems and Sturm-type nonoscillation',r'''The period vector is said to satisfy a differential equation, with a margin naming the Gauss--Manin connection. Arnold asks about a relation to oscillation theorems.''',r'''Over an interval of regular values of an algebraic family, transport a homology cycle continuously and integrate a basis of relative de Rham classes. These periods satisfy a linear Picard--Fuchs system with meromorphic coefficients. In the cubic elliptic case it reduces to a two-component system; scalar second-order equations and the Riccati equation for a ratio of periods permit zero estimates. Mere satisfaction of a linear ODE does not by itself imply the Chebyshev bound.''',r'''The distinction between a general period equation and a special nonoscillation argument is supplied. The marginal question has no separate quantified conjecture.''','E',r'''\citet[\S2.1--2.3]{petrov1986elliptic} explicitly uses Sturm separation and a Riccati reduction. These classical tools were already available; the new sharp estimate is indexed separately.''',r'''The specific connection to oscillation theory is verified in the contemporaneous proof. No unaddressed general theorem is extracted from the margin.''',['petrov1986elliptic'],match='partial')
item(642,'P001201','definition','Chebyshev spaces versus arbitrary linearly independent functions',r'''The page says that for linearly independent \(f_1,\ldots,f_N\), a linear combination has \(N-1\) zeros, and then defines Chebyshev spaces by an upper bound smaller than their dimension.''',r'''A real \(N\)-dimensional space of sufficiently differentiable functions on an interval is a Chebyshev space in the multiplicity convention used here if every nonzero function has at most \(N-1\) zeros counted with multiplicity. Linear independence alone gives no such upper bound: \(1\) and \(\sin t\) are independent on \((0,10\pi)\), but \(\sin t\) has nine interior zeros. Conversely, at any prescribed \(N-1\) distinct points, homogeneous linear algebra supplies a nonzero combination vanishing there; it does not give exactly that many zeros.''',r'''\ours{} The counterexample and the corrected existential statement are supplied here. The notebook may have compressed this lower-bound observation, but its literal universal reading is false.''','E',r'''The precise multiplicity convention is stated in \citet[\S1]{petrov1986elliptic}; the elementary counterexample independently checks the missing logical distinction.''',r'''The definition is standard. Linear independence and the Chebyshev property must remain separate.''',['petrov1986elliptic'],literal='false as written',match='partial',development='annotated')
item(642,'P001201','construction','The kernel of restriction and integration on a level curve',r'''The notes observe that exact differentials integrate to zero and that multiplication by \(H-c\) does not change the restricted form on \(H=c\).''',r'''For a smooth affine level curve \(C_c=\{H=c\}\), every closed cycle \(\gamma\) satisfies \(\int_\gamma dF=0\). Forms divisible by \(H-c\) restrict to zero, as do forms \(R\,dH\). Thus the period map factors through the algebraic de Rham quotient of the fiber. For the whole moving family, one instead uses forms modulo exact forms and multiples of \(dH\), with its \(\mathbb C[H]\)-module structure; \((H-c)\omega\) is not identically period-zero as the parameter varies.''',r'''The final distinction repairs a possible confusion between a fixed fiber and the family. The notebook does not claim that periods over one chosen oval detect the entire de Rham quotient.''','E',r'''These are direct restriction and Stokes identities. Their role in polynomial-period reduction is visible in \citet[\S2.1]{petrov1986elliptic}; that paper is cited for the application, not as the origin of the identities.''',r'''Established elementary facts. Additional hypotheses are required for any asserted identification of a relative module with all periods.''',['petrov1986elliptic'],match='partial')
item(642,'P001201','construction','Jacobian algebra of x cubed plus y to the fourth',r'''A displayed quotient for \(f=x^3+y^4\) and a lattice diagram record six monomials.''',r'''\oursComputed{} Over \(\mathbb C\), the local Jacobian algebra is \(\mathbb C[[x,y]]/(\partial_x f,\partial_y f)=\mathbb C[[x,y]]/(x^2,y^3)\). Its basis is \(1,y,y^2,x,xy,xy^2\), so its dimension is six. The singularity at the origin is isolated.''',r'''The basis and isolatedness are checked directly from the displayed derivatives; no theorem about all Newton diagrams is inferred.''','E',r'''This is a standard Jacobian-algebra computation, in the classical Newton/Milnor setting of \citet{kouchnirenko1976polyedres}. The cited original was opened; the numerical conclusion here is independently verified rather than quoted from it.''',r'''The value six is correct; the accompanying code verifies the standard monomial basis.''',['kouchnirenko1976polyedres'],literal='correct',match='thematic only',verification='indirect',development='annotated')
item(642,'P001201','construction','Jacobian algebra of x squared y plus y to the fourth',r'''The second lattice sketch is attached to \(f=x^2y+y^4\). It does not explicitly state a dimension.''',r'''\oursComputed{} Here the Jacobian ideal is \((2xy,x^2+4y^3)\). The quotient has basis \(1,x,y,y^2,y^3\): \(xy=0\), \(x^2=-4y^3\), and multiplication by \(y\) gives \(y^4=0\). A Groebner basis has leading monomials \(xy,x^2,y^4\), proving independence and dimension five. The common derivative zero is isolated.''',r'''The value five is our reconstruction and computation, not an omitted numeral claimed to have been read from the scan.''','E',r'''The example belongs to the same established Jacobian-algebra framework as the preceding item. \citet{kouchnirenko1976polyedres} supplies historical context; the exact basis is checked here directly.''',r'''Computation verified algebraically and by the accompanying code; it is an annotation, not new singularity theory.''',['kouchnirenko1976polyedres'],literal='correct with missing hypotheses',match='thematic only',verification='indirect',development='annotated')
problems.append(dict(id='GP-1985-01',title='Uniform degree bounds for zeros of Abelian integrals',statement=r'''For real polynomials \(H,P,Q\) of bounded degrees, bound the total isolated zeros, counted with multiplicity, of \(\int_{\gamma(t)}(P\,dx+Q\,dy)\) on the regular compact oval branches of \(H=t\), uniformly in the coefficients. Identically zero branches are excluded from the isolated-zero count.''',occurrences=['1985-642.1'],status=r'''As of November 2026, a finite explicit uniform bound is established by \citet[Theorem 2]{binyamininovikovyakovenko2010zeros} (preprint 2008; publication 2010). This addresses the precise first-period question, not Hilbert's full sixteenth problem. No exact earlier occurrence with this problem's quantifiers was found in the supplied index, which ends in 1982.''',status_date='2026-11',refs=['binyamininovikovyakovenko2010zeros']))
save()

talk(643,'1985-09-09','A. V. Zelevinsky','P001202-P001203 (top)','Jacobi triple product through binary words and partitions',r'''The correct expanded triple product is followed by an incorrect compressed Pochhammer version. Zelevinsky then gives a combinatorial proof through partitions, eventually constant binary words, a distinguished gap, and two sets of odd distances. The method is attributed in the notebook to Leibenzon; Arnold adds the Young-diagram interpretation. The proof is elementary exposition, not an unsolved partition identity. Related encodings occur at 1976-415.1 and 1981-548.1--2.''')
item(643,'P001202','theorem','Jacobi triple product',r'''The initial displayed formula is \(\sum_{r\in\mathbb Z}z^rq^{r^2}=\prod_{k\geq1}(1-q^{2k})(1+zq^{2k-1})(1+z^{-1}q^{2k-1})\).''',r'''The identity holds analytically for \(0<|q|<1\) and \(z\in\mathbb C^*\), with locally uniform convergence in \(z\), and formally as a \(q\)-series whose coefficients are Laurent polynomials in \(z\). The case \(q=0\) is obtained directly as the constant term.''',r'''Convergence or the formal-series interpretation is supplied. The independent combinatorial construction is indexed in the following items.''','E',r'''The classical identity is recorded in \citet[20.5.9]{nist2026dlmf}; this checked reference is an exposition of a result long predating 1985.''',r'''Established identity; the first display is correct.''',['nist2026dlmf'],literal='correct')
item(643,'P001202','definition','Pochhammer notation and the three incorrect arguments',r'''The notebook defines \((a;q)_\infty=\prod_{n\geq0}(1-aq^n)\) but rewrites the product as \((1;q^2)_\infty(-zq^{-1};q^2)_\infty(-z^{-1}q^{-1};q^2)_\infty\). The scan confirms the literal \(1\) and both negative exponents.''',r'''With the stated zero-based convention, the correct expression is \((q^2;q^2)_\infty(-zq;q^2)_\infty(-z^{-1}q;q^2)_\infty\). In particular \((1;q^2)_\infty=0\), so the recorded compressed formula cannot equal the theta series. This is an error in the notebook, not an error introduced by the transcription.''',r'''The correction follows by substituting the definition into each of the three factors; it changes all three arguments and leaves the expanded product unchanged.''','E',r'''The standard notation and product are checked against \citet[17.8.1 and 20.5.9]{nist2026dlmf}.''',r'''The emended expression is correct. The diplomatic reading remains documented separately.''',['nist2026dlmf'],literal='false as written',development='annotated')
item(643,'P001202','claim','The reference to Ramanujan summation',r'''An emphatic line says the triple product follows from Ramanujan's identity, without writing that identity.''',r'''A natural precise candidate is Ramanujan's bilateral summation \( {}_1\psi_1(a;b;q,z)=(q,b/a,az,q/(az);q)_\infty/(b,q/a,z,b/(az);q)_\infty\), valid away from poles for \(0<|q|<1\), \(|b/a|<|z|<1\). Here \({}_1\psi_1=\sum_{n\in\mathbb Z}(a;q)_n z^n/(b;q)_n\). A specialization and limit give the triple product.''',r'''Identification with \({}_1\psi_1\) is plausible but not uniquely forced by the unnamed reference. The notes contain no limiting argument; none is attributed to Zelevinsky.''','E',r'''The summation and its triple-product specialization are the classical formulas \citet[17.8.1--2]{nist2026dlmf}.''',r'''The mathematical relation is established; the intended Ramanujan identity remains a medium-confidence identification.''',['nist2026dlmf'],literal='not determinable',match='partial',confidence='medium')
item(643,'P001202','construction','Coefficient counting by two strict odd partitions',r'''After dividing by \(\prod_{k\geq1}(1-q^{2k})\), the coefficient of \(z^rq^{r^2+2n}\) on the left is \(p(n)\). The right is encoded by two decreasing lists \(\alpha,\beta\) of positive odd integers.''',r'''Choose two finite strictly decreasing sequences \(\alpha_1>\cdots>\alpha_s>0\) and \(\beta_1>\cdots>\beta_t>0\), all entries odd. Their weight in the right-hand product is \(z^{s-t}q^{\sum\alpha_i+\sum\beta_j}\). Thus the coefficient counts pairs with \(s-t=r\) and total sum \(r^2+2n\). Euler's product on the left gives \(p(n)\). Strictness is required because each factor may be selected at most once.''',r'''The product determines the meaning of the overwritten comparison signs in the beta list; it does not establish that every underlying handwritten stroke is a strict sign.''','E',r'''Euler's partition product and the triple product are classical; see \citet[Chapter I, \S1]{macdonald1995symmetric} and \citet[20.5.9]{nist2026dlmf}. The equality of the two counts is justified by the next bijection.''',r'''Correct coefficient interpretation. The strictness qualification is mathematical, and the doubtful scan reading remains marked as such.''',['macdonald1995symmetric','nist2026dlmf'],literal='correct with missing hypotheses',match='partial')
item(643,'P001202-P001203','construction','Eventually constant binary words and partition size',r'''Leibenzon's construction uses bi-infinite zero--one words, zeros sufficiently far to the left and ones sufficiently far to the right. The number of linkages equals the integer being partitioned.''',r'''Take binary words with only finitely many inversions \((i,j)\), \(i<j\), \(a_i=1,a_j=0\), and the stated tails, modulo translation of their indexing. Reading a zero as a horizontal step and a one as a vertical step produces the boundary of a finite Young diagram. Inversions correspond to its boxes; consequently translation classes with \(n\) inversions are in bijection with partitions of \(n\).''',r'''Taking words modulo translation, or equivalently choosing the unique charge-zero gap, is indispensable: otherwise every partition would have infinitely many shifted representatives.''','E',r'''The partition-boundary encoding is classical and consistent with \citet[Chapter I, \S1]{macdonald1995symmetric}, whose first edition appeared in 1979. The personal attribution to Leibenzon was not independently traced to a publication; that does not turn the elementary bijection into an open problem.''',r'''The construction is valid after specifying the indexing convention. Earlier related beta-number descriptions occur at 1981-548.1--2.''',['macdonald1995symmetric'],match='partial',verification='indirect',development='annotated',confidence='medium')
item(643,'P001203 (top)','construction','Gap charge and the two odd-distance sets',r'''Each gap is assigned the number of ones to its left minus the number of zeros to its right. The resulting integers are said to run through \(\mathbb Z\). The odd-distance lists read off from a gap give the two partitions.''',r'''\ours{} For a fixed word class and gap, put \(r=s-t\), where \(s\) counts left-hand ones and \(t\) right-hand zeros. Moving the gap one place right increases \(r\) by one, regardless of the intervening bit; the tail conditions make the values unbounded both ways. Therefore each integer charge selects exactly one gap. Distances \(1,3,5,\ldots\) from that gap to left ones and right zeros define \(\alpha,\beta\), and conversely these finite sets reconstruct the word with its gap.''',r'''The monotonicity proof and inversion of the encoding are explicit reconstructions of the notebook's compressed diagrams.''','E',r'''This is the elementary mechanism of the recorded proof; the standard Frobenius/partition framework appears in \citet[Chapter I, \S1]{macdonald1995symmetric}. No exact independent publication of this particular seminar attribution was found.''',r'''Verified combinatorial bijection. It supplies the missing uniqueness needed by the coefficient count.''',['macdonald1995symmetric'],match='partial',verification='indirect',development='annotated')
item(643,'P001203 (top)','claim','Young-diagram area equals half the odd sum minus charge squared',r'''Arnold draws the zero/right, one/up path and interprets the word as a Young-diagram boundary. The resulting relation is \(\sum\alpha_i+\sum\beta_j=r^2+2n\). A coordinate label \(x-y\) depends on the direction chosen for the vertical axis.''',r'''\ours{} Write \(\alpha_i=2a_i+1\), \(\beta_j=2b_j+1\). Counting inversions separately on the left, on the right, and across the gap gives \(n=\sum_i a_i+\sum_j b_j-s(s-1)/2-t(t-1)/2+st\). Hence \(\sum\alpha_i+\sum\beta_j=2n+(s-t)^2\). Together with the unique charge gap, this proves the coefficient equality and therefore the triple product.''',r'''\oursComputed{} The accompanying independent finite enumerations check the inversion identity, the odd-part counts, and the product coefficients. The general inversion proof is the one supplied above. For an upward-positive coordinate axis, the monotonically changing gap coordinate is \(x+y\); \(x-y\) works with the downward-positive Young-diagram convention. No definite transcription error is asserted solely from the sketch.''','E',r'''The conclusion is the classical identity in \citet[20.5.9]{nist2026dlmf}; the finite counting verification included with this chapter checks the reconstructed bijection independently.''',r'''The proof is complete under the explicit conventions. It is an annotation of an old identity, not a C/D development.''',['nist2026dlmf'],match='partial',verification='indirect',development='annotated',speaker='V. I. Arnold')
save()

talk(644,'1985-09-16','A. V. Zelevinsky, with A. A. Beilinson','P001203-P001204 (middle)','Reports on Vigneras, triple products, and trace Paley--Wiener',r'''The 16 September heading starts below the completed partition argument on P001203. It reports Vigneras's work and the Piatetski-Shapiro--Rallis triple product, then sketches the trace transform and unramified families. The separate Beilinson heading in the middle of P001204 belongs to this same meeting and concerns the quadratic Hermitian space and theta correspondence; it is not the 23 September Beilinson talk. Vigneras's intervening explanation at the top of P001204 has its own record 646.''')
item(644,'P001203','remark','Vigneras: from GL(2) over a quadratic extension to GSp(4)',r'''The first report is titled \ru{От \(GL_2(\mathbb Q(\sqrt d))\) к \(GSp_4(\mathbb Q)\)}. It mentions a lifting, its local counterpart, and Langlands functoriality.''',r'''The identifiable subject is transfer of suitable automorphic representations over a quadratic extension \(E/F\) toward symplectic similitude representations over \(F\). Here \(GSp_4(F)=\{g:g^tJg=\nu(g)J\}\). Locally the relevant four-dimensional induced parameters must preserve an alternating form up to a character. The notes give no central-character, cuspidality, or nonvanishing hypotheses, so they do not state a universal lift for every representation of \(GL_2(E)\).''',r'''The qualifications describe the scope that any precise lifting theorem needs, not missing claims supplied to the speaker.''','B',r'''The report matches the title of \citet{vigneras1986correspondances}, published in 1986; its author bibliography was checked. \citet[\S14]{gantakeda2011local} identify and revisit the quadratic-extension case of that work.''',r'''A specific historical construction is identified. Its full global hypotheses were not read in the inaccessible original, so no exact global theorem is claimed here.''',['vigneras1986correspondances','gantakeda2011local'],literal='not determinable',match='partial',verification='publisher metadata checked',confidence='medium')
item(644,'P001203','remark','The degree-eight triple-product L-function',r'''The second report names Rallis and Piatetski-Shapiro and writes \(L(s,\pi_1\times\pi_2\times\pi_3)\), for three representations of \(GL_2\).''',r'''For cuspidal automorphic representations \(\pi_i\) of \(GL_2(\mathbb A_F)\), the unramified local factor uses the tensor product of their two-dimensional Satake parameters: \(L_v(s)=\det(1-q_v^{-s}(t_{1,v}\otimes t_{2,v}\otimes t_{3,v}))^{-1}\), of degree eight. An integral representation then addresses continuation and a functional equation, with compatible central characters in its initial setup. The page records an announcement, not a statement of all analytic hypotheses.''',r'''The degree-eight factor is the exact meaning of the product notation; the completed ramified and archimedean factors are not reconstructed from the one-line report.''','B',r'''\citet[Introduction and \S3]{piatetskishapirorallis1987rankin} is the exact publication, received January 1986 and printed in 1987. Its introduction also records Garrett's communication of his integral construction in April 1985; this work already circulated before print.''',r'''The triple-product theory is established. This item is not evidence that arbitrary automorphic tensor-product functoriality was proved at the seminar.''',['piatetskishapirorallis1987rankin'],match='partial')
item(644,'P001203','construction','Hecke functions and trace characters',r'''A discussion associated with Jacquet asks how to use the trace formula. For locally constant compactly supported \(f\), it writes \(\pi(f)=\int_G f(g)\pi(g)\,dg\) and seeks to describe \(\pi\mapsto\operatorname{tr}\pi(f)\).''',r'''Let \(F\) be a nonarchimedean local field of characteristic zero, \(G=\mathbf G(F)\) for a connected reductive group, and fix Haar measure. The Hecke algebra \(\mathcal H(G)=C_c^\infty(G)\) has convolution product. For a smooth admissible representation of finite length, \(\pi(f)\) has finite rank, so its trace exists. Additivity in exact sequences makes this a linear form on the Grothendieck group \(R(G)\). The problem is the image of \(\mathcal H(G)\to R(G)^*\), not a Fourier transform on a naive manifold of irreducibles.''',r'''Admissibility, convolution, and the Grothendieck-group domain supply the missing analytic and algebraic hypotheses.''','E',r'''The construction is stated in \citet[\S1.1--1.2]{bernsteindelignekazhdan1986trace}; it was standard before the new image theorem. The latter is separately recorded at 1985-646.3.''',r'''Standard character theory. The name written as ``Jacket'' is bibliographically identified as Jacquet, without altering the diplomatic record.''',['bernsteindelignekazhdan1986trace'],match='exact')
item(644,'P001203','construction','Parabolic induction and unramified-character families',r'''The notes describe irreducible representations through induced representations from \(P=MU\), calling \(M\) the semisimple part, and varying a cuspidal representation by characters.''',r'''Here \(M\) is a reductive Levi factor, which generally has a center. Every irreducible smooth representation of \(G\) is a subquotient of normalized parabolic induction \(i_P^G(\rho)\) from a supercuspidal representation of a Levi, unique up to conjugacy as cuspidal support. Twisting \(\rho\) by unramified characters \(\chi\in X_{\rm nr}(M)\) produces algebraic families; neither all induced representations nor all their constituents are irreducible uniformly in \(\chi\).''',r'''``Semisimple part'' is corrected to Levi factor, and subquotient replaces any implied equality with an induced representation.''','E',r'''\citet[\S2.1]{bernsteindelignekazhdan1986trace} recall this established Bernstein theory, citing the earlier central-algebra work.''',r'''Established support theory. Reducibility loci explain why its parameter variety is not literally the irreducible dual.''',['bernsteindelignekazhdan1986trace'],literal='false as written',match='partial')
item(644,'P001203','remark','An unfinished comparison with the real and complex cases',r'''The final short line mentions the real case, possibly the complex case, and a difficult abbreviated word followed by ``on all Cartans''.''',r'''No definite theorem can be extracted: the line does not specify a function space, transform, growth condition, or the meaning of the abbreviation. Real-group Paley--Wiener theorems would be relevant background, but do not identify this statement.''',r'''No completion of the missing predicate is attempted.''','F',r'''Comparison with the precisely stated nonarchimedean theorem in \citet[\S1.2]{bernsteindelignekazhdan1986trace} and the primary Arthur publication list did not resolve the shorthand. The literature's thematic resemblance is not treated as an exact match.''',r'''Unidentified fragment, with no determinate open question to develop.''',['bernsteindelignekazhdan1986trace'],literal='not determinable',match='none found',verification='unresolved lead',confidence='low')
item(644,'P001204 (middle)','problem','Local Langlands packets for GSp(4)',r'''Under Beilinson's heading an arrow runs from irreducible representations of \(GSp_4\) to Weil--Deligne representations, with finite fibers called \(L\)-packets. The displayed field \(\mathbb Q\) must be read in the local discussion as \(\mathbb Q_p\).''',r'''For a nonarchimedean local field \(F\) of characteristic zero, classify \(\operatorname{Irr}GSp_4(F)\) by a surjective finite-to-one map to admissible homomorphisms \(W'_F\to GSp_4(\mathbb C)\), modulo conjugacy, with the expected central-character and local-factor compatibilities. Here \(W'_F\) denotes the Weil--Deligne group. Its fibers are the local \(L\)-packets.''',r'''The target dual group, local field, and compatibility requirement make precise the finite-fiber arrow. The notes alone do not establish exhaustion of all irreducibles.''','B',r'''\citet[Main Theorem, pp.~1842--1843]{gantakeda2011local} prove the correspondence for every such \(F\), including residue characteristic two; their preprint dates from June 2007. Their introduction explains the scope and exhaustion gap in the 1986 construction \citep{vigneras1986correspondances}, whose original was bibliographically checked.''',r'''Solved for \(GSp_4\) in the stated characteristic-zero local setting. This is not a claim about an unrestricted global automorphic classification.''',['gantakeda2011local','vigneras1986correspondances'],problem='GP-1985-02',speaker='A. A. Beilinson')
item(644,'P001204 (middle)','construction','Quadratic space of Hermitian two-by-two matrices',r'''The displayed matrices are \(\bigl(\begin{smallmatrix}x_1&x_2\\\bar x_2&x_3\end{smallmatrix}\bigr)\), and the determinant is a rational quadratic form. The invariant condition is abbreviated as \(x=\bar x\), although the display is Hermitian.''',r'''Let \(E/F\) be quadratic, \(\operatorname{char}F\ne2\), and let \(V=\{X\in M_2(E):X=\bar X^{\,t}\}\). Then \(\dim_FV=4\) and \(q(X)=\det X\) is a nondegenerate quadratic form over \(F\). The action \(X\mapsto gX\bar g^{\,t}\) of \(GL_2(E)\) satisfies \(q(gX\bar g^{\,t})=N_{E/F}(\det g)q(X)\), defining a homomorphism to \(GO(V,q)\).''',r'''\oursComputed{} The missing transpose and the similitude multiplier are supplied by direct matrix calculation. No surjectivity on \(F\)-points is asserted.''','E',r'''The quadratic-extension orthogonal-similitude construction is used in the Vigneras lift \citep{vigneras1986correspondances} and reviewed in \citet[\S14]{gantakeda2011local}; the elementary determinant identity is checked directly here.''',r'''Correct standard construction after the Hermitian condition is repaired.''',['gantakeda2011local','vigneras1986correspondances'],literal='false as written',match='partial',development='annotated',speaker='A. A. Beilinson')
item(644,'P001204 (middle)','method','Weil representation and the similitude theta correspondence',r'''The construction is said to use the Weil representation of \(GO_4\times GSp_4\).''',r'''For a four-dimensional quadratic space \(V\) and four-dimensional symplectic space \(W\) over a characteristic-zero local field, \(V\otimes W\) is symplectic. The usual oscillator construction restricts to the isometry dual pair \(O(V)\times Sp(W)\). With the tensor action, similitudes preserve the symplectic form only on \(R_0=\{(h,g):\nu_V(h)\nu_W(g)=1\}\). Extending the Weil representation to this subgroup and inducing to the relevant product produces the similitude theta representation. It is not a direct restriction of the fixed-character oscillator representation to an arbitrary full product of similitudes.''',r'''The compatible-multiplier subgroup and induced extension repair the schematic product notation; cover and character choices are part of the oscillator construction.''','B',r'''The exact similitude formalism was developed beyond the original isometry construction; \citet[\S2, especially p.~1847]{gantakeda2011local} spell out \(R_0\), its extension, and induction. The 1986 report \citep{vigneras1986correspondances} is the contemporaneous application, verified bibliographically.''',r'''Established method. The recorded phrase is informative shorthand, but not a complete definition of a representation.''',['gantakeda2011local','vigneras1986correspondances'],literal='correct with missing hypotheses',match='partial',speaker='A. A. Beilinson')
problems.append(dict(id='GP-1985-02',title='Local Langlands correspondence for GSp(4)',statement=r'''For every characteristic-zero nonarchimedean local field \(F\), construct the finite \(L\)-packet classification of irreducible smooth \(GSp_4(F)\)-representations by admissible Weil--Deligne parameters in \(GSp_4(\mathbb C)\), with the specified natural compatibilities.''',occurrences=['1985-644.6'],status=r'''As of November 2026, solved in this scope by \citet[Main Theorem]{gantakeda2011local}, first circulated in 2007 and published in 2011. Vigneras's 1986 work is an important predecessor, not evidence that the complete exhaustion had already been proved in 1985.''',status_date='2026-11',refs=['gantakeda2011local','vigneras1986correspondances']))

# This heading precedes Feigin's on the physical page even though the catalogue number is larger.
talk(646,'1985-09-16','M.-F. Vigneras','P001204 (top)','Bernstein support and the trace Paley--Wiener theorem',r'''Vigneras's short intervention continues the preceding trace-transform discussion. The two essential corrections are that the Bernstein variety parametrizes cuspidal support rather than individual irreducibles, and that the trace Paley--Wiener theorem requires a uniform compact-open invariance bound, in addition to algebraicity along induced families. The item is placed before record 645 because that is their order on the page.''')
item(646,'P001204 (top)','construction','The Bernstein variety is a support space, not the irreducible dual',r'''A disjoint union of unramified-character families modulo Weyl actions is equated with \(\operatorname{Irr}G\).''',r'''For a reductive \(p\)-adic group, let \(\Omega(G)\) be the set of conjugacy classes of supercuspidal pairs \((M,\rho)\). Its components are unramified-character tori, with finite stabilizer and relative Weyl quotients. Cuspidal support defines a surjective finite-to-one map \(\operatorname{Irr}G\to\Omega(G)\). At reducibility points different irreducible subquotients can have the same support; hence the displayed equality of sets is false in general.''',r'''The quotient notation is interpreted as an algebraic support variety. No choice of one constituent is hidden in it.''','E',r'''\citet[\S2.1]{bernsteindelignekazhdan1986trace} recall the earlier Bernstein support theory and state explicitly that the map is finite-to-one.''',r'''Standard theory, with the notebook's equality replaced by the support map.''',['bernsteindelignekazhdan1986trace'],literal='false as written',match='exact')
item(646,'P001204 (top)','claim','Regular trace functions along induced families',r'''The trace is said to be algebraic in the unramified character and to vanish on all but finitely many families.''',r'''For \(f\in C_c^\infty(G)\), any Levi \(M\), and irreducible smooth \(\rho\) of \(M\), the function \(\chi\mapsto\operatorname{tr}(i_P^G(\rho\otimes\chi)(f))\) is regular on \(X_{\rm nr}(M)\). One compact open subgroup can be chosen so that \(f\) is bi-invariant; its trace then vanishes on irreducibles having no vectors fixed by that subgroup. Only finitely many Bernstein components can contribute.''',r'''The stronger compact-open bound is made explicit; finiteness of components is a consequence, not a substitute for all compatibility conditions.''','E',r'''These necessary conditions are recorded in \citet[\S1.2 and \S2.3]{bernsteindelignekazhdan1986trace}, which treats them as immediate or established preliminaries to its new theorem.''',r'''Correct necessary properties of the trace transform.''',['bernsteindelignekazhdan1986trace'],match='exact')
item(646,'P001204 (top)','theorem','The precise trace Paley--Wiener image theorem',r'''The discussion identifies the trace-transform image using algebraicity and finite support in families; the preceding page attributes the theorem to Kazhdan and Bernstein.''',r'''A linear form \(\ell:R(G)\to\mathbb C\) is \(\ell([\pi])=\operatorname{tr}\pi(f)\) for some \(f\in\mathcal H(G)\) if and only if: (i) \(\chi\mapsto\ell(i_P^G(\sigma\otimes\chi))\) is regular for every standard Levi \(M\) and \(\sigma\in\operatorname{Irr}M\); and (ii) there is one compact open \(K\) such that \(\ell(E)=0\) whenever \(E^K=0\). The field and reductivity hypotheses are those of 1985-644.3.''',r'''The exact Grothendieck-group statement and condition (ii) come from the publication. Merely specifying regular functions on the support variety would lose information at reducibility points and is not this theorem.''','B',r'''\citet[\S1.2, theorem]{bernsteindelignekazhdan1986trace} prove the equivalence. The paper includes Deligne as coauthor, was received on 26 August 1985, and appeared in 1986. It was therefore circulating at the time of the talk.''',r'''Proved and correctly attributable to Bernstein--Deligne--Kazhdan. The seminar's short version omits a material hypothesis and one author.''',['bernsteindelignekazhdan1986trace'],literal='correct with missing hypotheses',match='exact')
save()

talk(645,'1985-09-16','B. L. Feigin','P001204 (bottom)-P001205','Worldsheets, area actions, and Polyakov integration',r'''Feigin describes string worldsheets and the passage from the induced-area functional to integration over a map and an independent metric. The formulas are the established Nambu--Goto and Polyakov constructions. Statements about all particles, a crystal-growth analogy, and an asserted operator/integral correspondence lack enough detail for theorem identification. The fixed-metric Gaussian step is precise; the full measure over surfaces is left formal. The continuation on 23 September begins only after Beilinson's conclusion on P001207.''')
item(645,'P001204 (bottom)','construction','String histories as maps of surfaces',r'''A closed string is represented by a circle, and its history sweeps out a surface mapped into space. The notes compare the construction with statistical mechanics on surfaces.''',r'''A parametrized closed string history is a map \(X:\Sigma\to\mathbb R^d\), with a cylindrical worldsheet in the simplest free propagation picture. Changes of the topology of \(\Sigma\) represent joining and splitting in perturbative string diagrams. The model requires a chosen target metric and an action; the topological picture alone determines no dynamics.''',r'''A worldsheet is the domain of a map and need not be an embedded surface in the target. The cylinder and topology-changing interpretation clarify the drawings.''','E',r'''The world-surface and random-surface formulation is explicit in \citet[p.~207, equations (1)--(2)]{polyakov1981quantum}, received in May and published in July 1981.''',r'''Established formulation; it is background for the action formulas below.''',['polyakov1981quantum'],match='partial')
item(645,'P001204 (bottom)','remark','The claim about all particles and a ten-dimensional superspace',r'''The notes suggest that all particles can be described through maps into a superspace denoted schematically by \(\mathbb R^{10/m}\).''',r'''The even dimension ten is recognizable from superstring theory, but the odd dimension \(m\), worldsheet fields, supersymmetry convention, and meaning of ``all particles'' are unspecified. No precise universal equivalence of particle theories is stated.''',r'''No identification with a particular ten-dimensional superstring model is imposed.''','F',r'''The bosonic random-surface paper \citet{polyakov1981quantum} and Witten's ten-dimensional twistor paper \citet{witten1986twistor} are adjacent contexts, not exact sources for this unrestricted assertion.''',r'''A programmatic remark whose mathematical content cannot be resolved further from the page; it is not indexed as an open conjecture.''',['polyakov1981quantum','witten1986twistor'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low')
item(645,'P001204 (bottom)','remark','The crystal-growth analogy',r'''A short comparison with crystal growth accompanies the picture of random surfaces.''',r'''No lattice, energy, probability measure, boundary condition, or limiting regime is specified. Thus no precise statistical-mechanical surface model or theorem can be reconstructed.''',r'''The analogy is retained as an identifiable intervention in the exposition without assigning it a research problem.''','F',r'''Random surfaces do occur in the physical motivation of \citet[p.~207]{polyakov1981quantum}, but this does not identify the notebook's specific crystal-growth comparison.''',r'''Unresolved model identification; no statement of a mathematical limit or universality class is justified.''',['polyakov1981quantum'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low')
item(645,'P001205','definition','The Nambu--Goto area functional',r'''The notebook writes \(L=\int(\det g_{ij})^{1/2}\,d\sigma\,d\tau\), with \(g\) induced by \(X\), followed by the explicit square-root formula in first derivatives.''',r'''For a smooth immersion \(X:\Sigma\to\mathbb R^d\) with Euclidean target metric, let \(h_{ab}=\partial_aX\cdot\partial_bX\). Its area action is \(S_{NG}[X]=T\int_\Sigma\sqrt{\det h}\,d^2\xi\), \(T>0\). In two coordinates, \(\det h=|X_\sigma|^2|X_\tau|^2-(X_\sigma\cdot X_\tau)^2\). For a timelike worldsheet in a Lorentzian target, the real area density instead uses \(\sqrt{-\det h}\).''',r'''The Euclidean convention makes the recorded square root literal; the tension is an optional positive scale absent from the displayed notebook normalization.''','E',r'''The identical Euclidean area formula appears in \citet[equation (3)]{polyakov1981quantum}, as classical geometric background.''',r'''Standard geometric action; no new variational theorem is asserted.''',['polyakov1981quantum'])
item(645,'P001205','definition','The formal sum over maps',r'''A Feynman integral is written \(\int e^{\beta L(X)}\,DX\).''',r'''This is a formal functional-integral prescription. A Euclidean convention uses \(e^{-S[X]}\), while a real-time convention uses \(e^{iS[X]/\hbar}\). Thus the recorded plus sign is not itself a transcription error: it depends on \(\beta\). To define an actual integral one must specify a regulator, boundary data, and the treatment of reparametrizations; no translation-invariant Lebesgue measure \(DX\) on all smooth maps is supplied.''',r'''The distinction between the symbolic prescription and a defined measure is explicit. No rigorous existence of the complete string path integral is attributed to this display.''','E',r'''\citet[equation (2) and the following discussion]{polyakov1981quantum} expressly treats the original surface sum as symbolic and develops a gauge-fixed prescription.''',r'''Established formal notation. Its mathematical definition depends on the chosen finite-dimensional or field-theoretic regularization.''',['polyakov1981quantum'],literal='correct with missing hypotheses',match='partial')
item(645,'P001205','claim','The asserted correspondence of operator and path-integral approaches',r'''The page says there are approaches by integrals and by ordinary operators, and that a correspondence has now been established.''',r'''The sentence does not identify the operator algebra, state space, dimension, anomaly conditions, boundary observables, or theorem of equivalence. A finite-dimensional Gaussian integral/operator correspondence does not establish equality of full interacting string theories.''',r'''No particular equivalence theorem is inserted into this unspecified announcement.''','F',r'''The opened Polyakov paper treats a path-integral formalism, but it does not supply a uniquely matching theorem for this sentence. Searches through that immediate bibliography did not identify what precise equivalence was being reported.''',r'''The statement remains unidentifiable at theorem level. It is not an unsolved problem with recoverable quantifiers.''',[],literal='not determinable',match='none found',verification='unresolved lead',confidence='low')
item(645,'P001205','definition','Polyakov action with an independent worldsheet metric',r'''The new integration variables are a pair \((X,g)\). The displayed action contains a metric-area term and a quadratic derivative term, with the first integration measure suppressed.''',r'''For a fixed smooth compact surface \(\Sigma\), independent positive Riemannian metric \(g\), and map \(X:\Sigma\to\mathbb R^d\), write \(S_P[X,g]=\lambda\int_\Sigma d\operatorname{vol}_g+(T/2)\int_\Sigma g^{ab}\partial_aX\cdot\partial_bX\,d\operatorname{vol}_g\). The second term is quadratic in \(X\) for fixed \(g\). With \(\lambda=0\), variation in \(g\) makes \(g\) conformal to the induced metric at nondegenerate critical points; a nonzero cosmological term changes that classical variational statement.''',r'''The integration measures and coefficients are normalized explicitly. Classical equivalence with area is not asserted for arbitrary \(\lambda\), nor is quantum equivalence inferred from the change of variables.''','E',r'''See \citet[equations (6)--(7) and (14)]{polyakov1981quantum}; the independent-metric functional and the cosmological weight were published in 1981.''',r'''Established formalism with the stated variational qualification. The notebook's missing measure is a harmless notational omission once supplied.''',['polyakov1981quantum'],match='exact')
item(645,'P001205','method','Integrate the map first: a Gaussian determinant',r'''The closing instruction is to fix \(g_{ij}\) and integrate over \(X\), since the action is quadratic.''',r'''On a closed connected Riemannian surface, expand each scalar component of \(X\) in Laplacian eigenfunctions. After removing the constant mode and retaining finitely many positive eigenvalues \(\lambda_1,\ldots,\lambda_N\), the integral is proportional to \(\prod_{j=1}^N\lambda_j^{-d/2}\), with the normalization depending on \(T\). A zeta-regularized continuum notation is \((\det'\Delta_g)^{-d/2}\); the prime records the omitted zero mode. This calculation leaves the metric integral and its gauge factors to be treated.''',r'''The finite-mode integral supplies an exact meaning to the Gaussian step. The determinant notation is an explicit modern reconstruction, not a formula written on this page.''','E',r'''The procedure is the integration step following \citet[equation (14)]{polyakov1981quantum}. Its finite-dimensional justification is ordinary Gaussian integration.''',r'''The fixed-metric calculation is standard; it does not by itself construct the remaining measure over metrics.''',['polyakov1981quantum'],match='partial')

talk(647,'1985-09-23','I. M. Gelfand','P001206 (top)','A central diagonal section of the four-dimensional cube',r'''Gelfand poses one elementary geometry problem, explicitly addressed to a ninth-grade audience. The answer is a regular octahedron; a complete coordinate verification is supplied as an annotation. The question is not an unresolved research problem.''')
item(647,'P001206 (top)','problem','Which polyhedron is the diagonal-orthogonal central section of a four-cube?',r'''\ru{Задача (для 9 кл.)}: what polyhedron results from cutting a four-dimensional cube through its center by a three-dimensional hyperplane perpendicular to a main diagonal?''',r'''\ours{} For the cube \([-1,1]^4\), the section is \(P=\{x:|x_i|\leq1,\ x_1+x_2+x_3+x_4=0\}\). Its vertices are exactly the six permutations of \((1,1,-1,-1)\). Set \(u_1=(1,1,-1,-1)\), \(u_2=(1,-1,1,-1)\), \(u_3=(1,-1,-1,1)\). They are pairwise orthogonal, each of length two, and \(P=\operatorname{conv}\{\pm u_1,\pm u_2,\pm u_3\}\). Hence \(P\) is a regular octahedron.''',r'''The supplied proof is as follows: a vertex of the three-dimensional section needs at least three active cube-coordinate bounds; the fourth coordinate is then forced to \(\pm1\), with exactly two plus signs. Orthogonality identifies the resulting cross-polytope. There are twelve equal edges of length \(2\sqrt2\) and eight equilateral triangular faces.''','E',r'''This is an elementary classical-polytope exercise, not an announcement requiring a later research solution. The direct proof and the independently enumerated vertices and edge lengths establish the answer without claiming an unverified historical attribution.''',r'''Completely solved in the stated setting. \oursComputed{} The accompanying independent exact-arithmetic enumeration confirms the vertices, edge lengths, and faces.''',[],literal='correct',match='none found',verification='indirect',development='annotated',problem='GP-1985-03')
problems.append(dict(id='GP-1985-03',title='Central section of a four-cube perpendicular to a main diagonal',statement=r'''Identify, up to Euclidean similarity, \([-1,1]^4\cap\{x_1+x_2+x_3+x_4=0\}\).''',occurrences=['1985-647.1'],status=r'''As of November 2026: an elementary solved exercise. The section is a regular octahedron, proved in 1985-647.1 and independently checked by exact enumeration in this chapter. The index retains this explicit posed question while the E classification records that no research novelty is claimed.''',status_date='2026-11',refs=[]))
save()

talk(648,'1985-09-23','A. A. Beilinson, with I. M. Gelfand interventions','P001206-P001207 (upper)','Adeles, automorphic representations, Satake parameters, and L-functions',r'''Beilinson introduces the automorphic setting for the announced work of Piatetski-Shapiro and Rallis. Gelfand explains p-adic expansions and points to Connes's Bourbaki lecture. The mathematical core passes from adeles and congruence quotients to restricted tensor products, spherical representations, dual groups, and Euler factors. Several handwritten shortcuts are false literally: the unrestricted product of completions, the punctured-sphere descriptions, and the suggestion that local representation lists alone determine the automorphic spectrum. The general occurrence problem is separated from the already established formalism.''')
item(648,'P001206','construction','The automorphic L2 representation and its spectral decomposition',r'''The opening task is to describe the action of the adelic group in \(L^2(G(\mathbb A)/G(\mathbb Q))\); the corresponding representations are called automorphic. The heading mentions the new Rallis--Piatetski-Shapiro work on functional equations.''',r'''For a connected semisimple group \(G/\mathbb Q\), use the equivalent left-quotient convention \(L^2(G(\mathbb Q)\backslash G(\mathbb A))\), with right translation. Its decomposition includes a discrete Hilbert sum and, in the noncompact case, continuous direct integrals induced from discrete automorphic data on Levi subgroups. The word automorphic also has a broader smooth moderate-growth definition; it is not synonymous with every Hilbert-space subrepresentation. For \(GL_n\), a reductive rather than semisimple example, one fixes a central character or removes the split center to obtain the usual finite-volume setting.''',r'''Quotient convention, continuous spectrum, and the reductive example are clarified. The abstract spectral theorem is separated from the arithmetic occurrence problem below.''','E',r'''The pre-1985 theory is summarized precisely in \citet[Theorem 3.3 and p.~28]{arthur1981automorphic}; its lecture setting was 1980 and publication 1981.''',r'''Established spectral formalism. It does not supply a complete arithmetic list of the cuspidal representations.''',['arthur1981automorphic'],match='partial')
item(648,'P001206','definition','Gelfand: p-adic expansions and the expansion of one third',r'''Gelfand writes finite base-\(p\) expansions, infinite expansions for rational numbers, the \(p\)-adic norm, and \(1/3=1+2+2^3+2^5+\cdots\) for \(p=2\). The coprimality condition in the norm formula is written \((a,m)=1\).''',r'''Every nonzero \(x\in\mathbb Q_p\) has a unique expansion \(x=\sum_{j=N}^{\infty}a_jp^j\), where \(N\in\mathbb Z\), \(a_j\in\{0,\ldots,p-1\}\), and \(a_N\ne0\); then \(|x|_p=p^{-N}\). Thus for \(a=p^nm\), the required condition is that \(m\) is a \(p\)-adic unit, not \((a,m)=1\). \oursComputed{} The displayed series equals \(1+2\sum_{j\geq0}4^j=1+2/(1-4)=1/3\) in \(\mathbb Q_2\), since \(|4|_2<1\).''',r'''Digits, convergence, and the unit condition are made explicit. The infinite expansion is a completion statement, not a convergent real-number series.''','E',r'''These classical completion facts are checked in \citet[\S7, Theorem 7.23 and the following examples]{milne2020ant}; the source is a modern exposition, not the origin of the result.''',r'''The one-third example is correct. \oursComputed{} For \(S_N=1+2\sum_{j=0}^{N-1}4^j\), exact arithmetic gives \(3S_N-1=2\cdot4^N\), with 2-adic valuation \(2N+1\); this independently verifies the partial sums. The norm\textquotesingle s unit condition is emended.''',['milne2020ant'],literal='false as written',development='annotated',speaker='I. M. Gelfand')
item(648,'P001206','definition','The adele ring is a restricted product including the real place',r'''The notes write adeles as \(\prod_p(\text{p-adic numbers})\).''',r'''The adele ring of \(\mathbb Q\) is \(\mathbb A_\mathbb Q=\mathbb R\times\prod'_p\mathbb Q_p\), where \(x_p\in\mathbb Z_p\) for all but finitely many primes. The restricted-product topology is used. Its finite part is \(\mathbb A_f=\prod'_p\mathbb Q_p\); the unrestricted product \(\prod_p\mathbb Q_p\) is a different object. The diagonal rational field is discrete in the full adele ring.''',r'''Both the restriction and archimedean factor are missing from the recorded shorthand; neither is optional for the later quotient formula.''','E',r'''\citet[\S2, pp.~10--11]{arthur1981automorphic} gives exactly this adelic setup in a source preceding the talk.''',r'''Standard definition. The notebook formula must be read as shorthand and is false as a literal equality.''',['arthur1981automorphic'],literal='false as written')
item(648,'P001206','definition','Principal congruence subgroups and divisibility of levels',r'''The chain \(SL_2(\mathbb R)\supset SL_2(\mathbb Z)\supset\Gamma_n\) is accompanied by the condition that matrices are the identity modulo \(n\), and \(\Gamma_{n_1}\supset\Gamma_{n_2}\) when \(n_1\mid n_2\).''',r'''For \(N\geq1\), \(\Gamma(N)=\ker(SL_2(\mathbb Z)\to SL_2(\mathbb Z/N\mathbb Z))\). If \(N\mid M\), reduction modulo \(N\) factors through reduction modulo \(M\), hence \(\Gamma(M)\subseteq\Gamma(N)\). Levels form a directed set under divisibility, not merely their usual numerical order.''',r'''The group and the direction of the inverse system are made explicit.''','E',r'''The definitions and indices are classical; see \citet[\S2, Example 2.23]{milne2017modular}.''',r'''Correct elementary congruence-group statement.''',['milne2017modular'],literal='correct')
item(648,'P001206','construction','Adelic quotient as the inverse limit of congruence quotients',r'''The display identifies \(G(\mathbb A)/G(\mathbb Q)\) with an inverse limit of \(G(\mathbb R)/\Gamma_n\), following the \(SL_2\) example.''',r'''For \(G=SL_2\) and principal compact open subgroups \(K(N)\subset SL_2(\widehat{\mathbb Z})\), strong approximation gives \(G(\mathbb Q)\backslash G(\mathbb A)/K(N)\simeq\Gamma(N)\backslash G(\mathbb R)\). Taking the inverse limit over divisible levels recovers \(G(\mathbb Q)\backslash G(\mathbb A)\) as a topological space. Inverting elements gives the right-quotient convention of the notebook. For a general reductive group the finite-level quotient may have several arithmetic components, so the unqualified single-quotient formula need not hold.''',r'''The statement is restricted to the explicit \(SL_2\) example; strong approximation is not silently assumed for every \(G\).''','E',r'''\citet[\S2, pp.~12--13]{arthur1981automorphic} explicitly uses strong approximation for \(SL_n\) and relates adelic level quotients to principal congruence quotients.''',r'''Correct in the stated \(SL_2\) setting. A general-group version needs its component set and strong-approximation hypotheses.''',['arthur1981automorphic'],match='partial')
item(648,'P001206','claim','Modular curves: cusps are not elliptic points',r'''The notes call \(\mathfrak H/\Gamma_n\) a punctured sphere, say \(\mathfrak H/SL_2(\mathbb Z)\) is a sphere with two punctures, and correctly give three punctures for \(\Gamma_2\).''',r'''As a coarse Riemann surface, \(SL_2(\mathbb Z)\backslash\mathfrak H\simeq\mathbb C\): its compactification is a sphere with one cusp removed; it also has two orbifold points of orders two and three, which are not punctures. \(\Gamma(2)\backslash\mathfrak H\) is a sphere minus three cusps. Principal congruence curves are not all genus zero: the compactification of \(\Gamma(7)\backslash\mathfrak H\) has genus three (already level six has genus one).''',r'''The distinction between the coarse curve, its orbifold structure, and removed cusps repairs both inaccurate sphere assertions.''','E',r'''\citet[Proposition 2.21, Theorem 2.22, Example 2.23]{milne2017modular} give the compactification, genus formula, and explicit level table, all read directly.''',r'''The \(\Gamma(2)\) statement is correct; the other two literal descriptions are false. This is a notebook error rather than a newly discovered exception.''',['milne2017modular'],literal='false as written',development='annotated')
item(648,'P001206','theorem','Restricted tensor products of local representations',r'''The representation of \(G(\mathbb A)\) is written as a tensor product of its real and all \(p\)-adic factors.''',r'''An irreducible admissible automorphic representation factors as \(\pi\simeq\bigotimes'_v\pi_v\), with irreducible admissible local factors (using the appropriate archimedean category). At almost all finite places there is a chosen nonzero \(K_v\)-fixed vector, and the restricted tensor product is the span of tensors equal to those vectors outside a finite set. It is not the unrestricted algebraic tensor product of an infinite collection of spaces.''',r'''The prime, almost-everywhere spherical condition, and specified reference vectors are added.''','E',r'''The standard factorization is recorded in \citet[Part I, \S1]{arthurgelbart1991lectures}, with its earlier source cited there, and already in \citet[p.~11]{arthur1981automorphic}.''',r'''Established factorization. Knowing possible local factors is still insufficient to decide which products are automorphic.''',['arthurgelbart1991lectures','arthur1981automorphic'],match='exact')
item(648,'P001206','remark','Gelfand points to Connes on subfactors and knots',r'''Gelfand notes that a Bourbaki lecture by A. Connes relates knot theory to factor isomorphisms.''',r'''The identifiable lecture connects finite-index subfactors, Hecke-type relations, braid-group representations and traces, leading to Jones's knot invariant. The notebook supplies no specific assertion that knot equivalence is classified by factor isomorphism.''',r'''The literal phrase ``factor isomorphisms'' is not expanded into a nonexistent classification theorem.''','E',r'''The exact match is \citet{connes1986indice}, Bourbaki expos\'e 647, delivered in June 1985 and printed in the 1986 Ast\'erisque volume. The title, dated lecture, and opening mathematical explanation were read.''',r'''A securely identified pre-talk report. Its print year alone would misclassify it as later development.''',['connes1986indice'],match='partial',speaker='I. M. Gelfand')
item(648,'P001206','problem','Which restricted products actually occur automorphically?',r'''After the tensor-product formula, the page asks which representations occur in \(L^2(G(\mathbb A)/G(\mathbb Q))\), adding that not all do. A preceding sentence says it is enough to know representations of the \(p\)-adic groups.''',r'''For a connected semisimple \(G/\mathbb Q\), determine which irreducible admissible restricted products \(\pi=\bigotimes'_v\pi_v\) occur in the discrete automorphic spectrum, and their multiplicities. More generally, identify the inducing automorphic data governing the continuous spectrum. Local admissibility and almost-everywhere sphericality are necessary but do not decide global occurrence; the archimedean factor and global conditions matter.''',r'''The discrete multiplicity formulation makes the question precise; it is distinguished from the abstract Eisenstein-series decomposition already known in 1985. No equivalence with every version of the Langlands conjectures is asserted.''','C',r'''\citet[Theorem 3.3]{arthur1981automorphic} supplies the established spectral structure. A major later partial classification is Arthur's orthogonal/symplectic theory: the 2013 monograph \citep{arthur2013endoscopic} was bibliographically checked, and the author explains its scope and the larger classification goal in \citet[\S4]{arthur2018functoriality}.''',r'''A general arithmetic occurrence and multiplicity classification for every connected semisimple group is not supplied by these results. The reviewed primary literature establishes major group-specific classifications, while the unrestricted problem remains a broad program. The supplied earlier index contains related automorphy questions, including GP-1982-43, with different quantifiers; they are not merged.''',['arthur1981automorphic','arthur2013endoscopic','arthur2018functoriality'],literal='correct with missing hypotheses',match='partial',verification='read the result',problem='GP-1985-04',worth=r'''Worth pursuing only after fixing a group and a narrowly specified packet or multiplicity question; the unrestricted classification does not offer a plausible bounded contribution in this chapter.''',confidence='medium')
item(648,'P001206-P001207','definition','Spherical representations and unramified principal series',r'''The simplest local representations have a vector fixed by a maximal compact subgroup; the notes then use induction from a triangular Borel and characters trivial on the compact part of a torus.''',r'''Let \(G/F\) be a split connected reductive group over a nonarchimedean local field, with a fixed split integral model and hyperspecial \(K=G(\mathcal O_F)\). An irreducible smooth representation is \(K\)-spherical if \(\pi^K\ne0\); then \(\dim\pi^K=1\). Every such representation is the unique spherical irreducible subquotient of normalized induction from an unramified character of a split maximal torus. The full induced representation can be reducible.''',r'''Hyperspecial \(K\), normalization, and ``subquotient'' are essential. ``A maximal compact'' without specifying the unramified setting is too broad for the displayed parametrization.''','E',r'''\citet[\S6]{satake1963spherical} establishes the spherical framework, and \citet[Part I, \S1]{arthurgelbart1991lectures} explicitly describes the unramified principal-series interpretation.''',r'''Established unramified representation theory, with the stated subgroup and group hypotheses.''',['satake1963spherical','arthurgelbart1991lectures'],match='exact')
item(648,'P001207 (upper)','theorem','Satake parameters as semisimple dual-group conjugacy classes',r'''Unramified torus characters are identified with points of a dual torus; spherical representations are written as \(T^0(\mathbb C)/W\) and then as conjugacy classes of matrices.''',r'''For split \(G/F\) as above, \(X_{\rm nr}(T)=\operatorname{Hom}(T(F)/T(\mathcal O_F),\mathbb C^*)\simeq\widehat T(\mathbb C)\), after fixing a uniformizer. The normalized Satake isomorphism identifies the spherical Hecke algebra with \(\mathbb C[X_*(T)]^W\). Its characters correspond to \(\widehat T(\mathbb C)/W\), equivalently semisimple conjugacy classes in the complex dual group \(\widehat G\). These are not arbitrary matrix conjugacy classes until a representation of \(\widehat G\) is chosen.''',r'''The Hecke-algebra step and semisimplicity explain the quotient and remove the ambiguous reference to matrices.''','E',r'''This is Satake's classical theorem, \citet[\S6, Theorem 3]{satake1963spherical}, published in 1963.''',r'''Established classification of the unramified spherical spectrum.''',['satake1963spherical'])
item(648,'P001207 (upper)','definition','The complex dual group and a chosen representation',r'''The notes introduce \(G^0\), call it the dual group, give \(GL_n\) as self-dual, and choose \(\rho:G^0\to GL_m(\mathbb C)\).''',r'''For a split connected reductive group with root datum \((X^*,\Phi,X_*,\Phi^\vee)\), its complex dual group \(\widehat G\) has datum \((X_*,\Phi^\vee,X^*,\Phi)\). In particular \(\widehat{GL_n}=GL_n(\mathbb C)\). A finite-dimensional algebraic representation \(\rho\) converts a semisimple Satake class into a well-defined matrix characteristic polynomial. For nonsplit groups one needs the full \(L\)-group with Galois action; the notes explicitly restrict to split groups here.''',r'''The root datum definition is supplied, keeping the stated split hypothesis.''','E',r'''The pre-talk dual-group construction and resulting factors are presented in \citet[\S5, pp.~37--44]{arthur1981automorphic}.''',r'''Standard Langlands formalism; no self-duality of every reductive group is implied by the \(GL_n\) example.''',['arthur1981automorphic'],match='exact')
item(648,'P001207 (upper)','definition','Unramified Euler factors and the partial automorphic L-function',r'''For almost all spherical local factors, the notes write \(L(\pi,\rho,s)=\prod_p\det(1-p^{-s}\rho(x_{\pi_p}))^{-1}\).''',r'''For an automorphic representation of a split reductive group over \(\mathbb Q\), choose a finite set \(S\) containing all ramified primes. At \(p\notin S\), let \(t_p\in\widehat G\) be the normalized Satake class and put \(L_p(s,\pi,\rho)=\det(1-p^{-s}\rho(t_p))^{-1}\). The displayed construction defines the partial Euler product \(L^S(s,\pi,\rho)=\prod_{p\notin S}L_p(s,\pi,\rho)\) in its domain of convergence. Bad-prime and archimedean factors are additional data for a completed function; analytic continuation and a functional equation do not follow merely from writing the product.''',r'''The superscript \(S\) resolves the inconsistency between ``almost all'' and a product over every prime. No general analytic-continuation conjecture is introduced as a new question stated on this page.''','E',r'''The precise pre-1985 construction is \citet[\S5, pp.~43--44]{arthur1981automorphic}; \citet[\S1]{arthur2018functoriality} retains the partial-product convention and separates it from analytic conjectures.''',r'''The definition is established. Its unrestricted analytic properties remain outside what the notebook asserts; particular triple-product results are indexed at 1985-644.2.''',['arthur1981automorphic','arthur2018functoriality'],match='exact')
item(648,'P001207 (upper)','remark','The trivial GL(1) example is the Riemann zeta function',r'''The final example chooses the identity representation \(GL_1\to GL_1\), then the trivial Satake parameter \(x=1\), obtaining \(\prod_p(1-p^{-s})^{-1}\).''',r'''For the trivial automorphic character of \(\mathbb A_\mathbb Q^*/\mathbb Q^*\) and the standard one-dimensional representation of \(\widehat{GL_1}\), the finite Euler product is \(\zeta(s)=\prod_p(1-p^{-s})^{-1}\) for \(\operatorname{Re}s>1\). Its usual completed expression adds \(\pi^{-s/2}\Gamma(s/2)\). This example uses a reductive group, extending the opening semisimple shorthand.''',r'''The half-plane of convergence and distinction between finite and completed factors are added; the notebook only writes the finite product.''','E',r'''This is the classical Euler product, appearing as the basic \(GL_1\) case in \citet[Part I, \S1]{arthurgelbart1991lectures}.''',r'''Established example; it does not constitute a proof of analytic properties for every higher-dimensional Euler product.''',['arthurgelbart1991lectures'],literal='correct')
problems.append(dict(id='GP-1985-04',title='Arithmetic occurrence and multiplicity in the automorphic spectrum',statement=r'''For a fixed connected semisimple \(G/\mathbb Q\), determine which irreducible admissible restricted products of local representations occur in the discrete spectrum of \(L^2(G(\mathbb Q)\backslash G(\mathbb A))\), and their multiplicities; the unrestricted seminar question ranges over such groups. Distinguish this arithmetic classification from the already established decomposition by Eisenstein series.''',occurrences=['1985-648.9'],status=r'''As of November 2026: partly developed, with major classifications for specific families of groups, exemplified by Arthur's orthogonal/symplectic theory. The cited results do not give the unrestricted classification. The problem is too broad for a bounded new contribution without choosing a group and a particular packet or multiplicity. GP-1982-43 concerns a different automorphy question and is linked contextually, not merged.''',status_date='2026-11',refs=['arthur1981automorphic','arthur2013endoscopic','arthur2018functoriality']))
save()

